INSERT INTO `career_paths` (`id`, `title`, `slug`, `description`, `target_role`, `price`, `status`, `cover_url`, `certificate_template_id`, `created_by`, `published_at`, `created_at`, `updated_at`) VALUES (1,'Lập trình viên Fullstack','cntt-fullstack-developer','Lộ trình CNTT: từ HTML/CSS/JS nâng cao đến frontend framework, backend, database và triển khai Docker/CI-CD.','cntt_fullstack',1500000,'published','https://images.unsplash.com/photo-1498050108023-c5249f4df085?w=1400&q=80',1,8,'2026-08-09 15:25:23','2026-08-12 14:35:35','2026-08-12 15:25:23'),(2,'DevOps Engineer','cntt-devops-engineer','Lộ trình CNTT: Linux, Docker/Kubernetes, CI/CD, Cloud và Monitoring/Logging cho vận hành hệ thống.','cntt_devops',1500000,'published','https://images.unsplash.com/photo-1667372393119-3d4c48d07fc9?w=1400&q=80',1,5,'2026-08-09 15:25:23','2026-08-12 14:35:35','2026-08-12 15:25:23'),(3,'Data Analyst / Data Engineer','cntt-data-analyst-engineer','Lộ trình CNTT: SQL nâng cao, Python data stack, BI, ETL/Data Warehouse và thống kê ứng dụng.','cntt_data',1500000,'published','https://images.unsplash.com/photo-1551288049-bebda4e38f71?w=1400&q=80',1,10,'2026-08-09 15:25:24','2026-08-12 14:35:35','2026-08-12 15:25:24'),(4,'Kỹ sư kiểm thử phần mềm (QA/Tester)','cntt-qa-tester','Lộ trình CNTT: Manual Testing, Automation (Selenium/Cypress), API testing và quy trình QA.','cntt_qa',1200000,'published','https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=1400&q=80',1,6,'2026-08-09 15:25:24','2026-08-12 14:35:35','2026-08-12 15:25:24'),(5,'Chuyên viên An toàn thông tin','cntt-cybersecurity','Lộ trình CNTT: mạng nâng cao, Penetration Testing, chứng chỉ CEH/Security+ và Linux hardening.','cntt_security',1200000,'published','https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=1400&q=80',1,10,'2026-08-09 15:25:24','2026-08-12 14:35:36','2026-08-12 15:25:24'),(6,'Lập trình viên Mobile','cntt-mobile-developer','Lộ trình CNTT: Flutter/React Native (hoặc native), tích hợp API, UI/UX mobile và publish Store.','cntt_mobile',1200000,'published','https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=1400&q=80',1,6,'2026-08-09 15:25:24','2026-08-12 14:35:36','2026-08-12 15:25:24'),(7,'Kỹ sư AI/Machine Learning','cntt-ai-ml-engineer','Lộ trình CNTT: Python chuyên sâu, toán xác suất & đại số tuyến tính, TensorFlow/PyTorch, Deep Learning & NLP/CV.','cntt_ai_ml',1200000,'published','https://images.unsplash.com/photo-1677442136019-21780ecad995?w=1400&q=80',1,10,'2026-08-09 15:25:24','2026-08-12 14:35:36','2026-08-12 15:25:24'),(8,'Chuyên viên Digital Marketing','qtkd-digital-marketing','Lộ trình QTKD: SEO/SEM, Social, Content, Analytics/Ads và Marketing Automation.','qtkd_digital_marketing',1500000,'published','https://images.unsplash.com/photo-1533750349088-cd871a92f312?w=1400&q=80',1,7,'2026-08-09 15:25:25','2026-08-12 14:35:36','2026-08-12 15:25:25'),(9,'Chuyên viên/Quản lý Bán hàng','qtkd-sales-management','Lộ trình QTKD: kỹ năng bán hàng, CRM, đàm phán & CSKH, quản trị kênh phân phối.','qtkd_sales',1200000,'published','https://images.unsplash.com/photo-1556745757-8d76bdb6984b?w=1400&q=80',1,11,'2026-08-09 15:25:25','2026-08-12 14:35:36','2026-08-12 15:25:25'),(10,'Chuyên viên Nhân sự (HR)','qtkd-human-resources','Lộ trình QTKD: tuyển dụng, C&B, Luật lao động, đào tạo & phát triển nhân sự.','qtkd_hr',1200000,'published','https://images.unsplash.com/photo-1521737604893-d14cc237f11d?w=1400&q=80',1,7,'2026-08-09 15:25:25','2026-08-12 14:35:36','2026-08-12 15:25:25'),(11,'Chuyên viên Tài chính - Kế toán','qtkd-finance-accounting','Lộ trình QTKD: kế toán nâng cao, phân tích BCTC, Excel/Power BI tài chính và ACCA/CFA cơ bản.','qtkd_finance',1200000,'published','https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=1400&q=80',1,11,'2026-08-09 15:25:25','2026-08-12 14:35:37','2026-08-12 15:25:25'),(12,'Quản lý Dự án (Project Manager)','qtkd-project-manager','Lộ trình QTKD: Agile/Scrum, PMP/PMI cơ bản, quản trị rủi ro và công cụ Jira/Trello/MS Project.','qtkd_pm',1200000,'published','https://images.unsplash.com/photo-1531403009284-440f080d1e12?w=1400&q=80',1,7,'2026-08-09 15:25:25','2026-08-12 14:35:37','2026-08-12 15:25:25'),(13,'Khởi nghiệp / Quản trị doanh nghiệp','qtkd-startup-management','Lộ trình QTKD: Business Plan, quản trị chiến lược, tài chính khởi nghiệp và gọi vốn.','qtkd_startup',1200000,'published','https://images.unsplash.com/photo-1552664730-d307ca884978?w=1400&q=80',1,11,'2026-08-09 15:25:26','2026-08-12 14:35:37','2026-08-12 15:25:26'),(14,'Chuyên viên Xuất nhập khẩu - Logistics','qtkd-import-export-logistics','Lộ trình QTKD: nghiệp vụ XNK, Incoterms, chuỗi cung ứng và hải quan điện tử.','qtkd_logistics',1200000,'published','https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?w=1400&q=80',1,7,'2026-08-09 15:25:26','2026-08-12 14:35:38','2026-08-12 15:25:26'),(15,'Kỹ sư mạng viễn thông (Network Engineer)','dtvt-network-engineer','Lộ trình ĐTVT: CCNA/CCNP, mạng IP & định tuyến, 4G/5G, quản lý & vận hành hệ thống mạng.','dtvt_network',1200000,'published','https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=1400&q=80',1,11,'2026-08-09 15:25:26','2026-08-12 14:35:38','2026-08-12 15:25:26'),(16,'Kỹ sư IoT','dtvt-iot-engineer','Lộ trình ĐTVT: vi điều khiển, cảm biến & truyền thông không dây, MQTT/CoAP, Cloud IoT.','dtvt_iot',1200000,'published','https://images.unsplash.com/photo-1518770660439-4636190af475?w=1400&q=80',1,7,'2026-08-09 15:25:26','2026-08-12 14:35:38','2026-08-12 15:25:26'),(17,'Kỹ sư thiết kế vi mạch (IC Design)','dtvt-ic-design','Lộ trình ĐTVT: Verilog/VHDL, FPGA, quy trình VLSI và công cụ EDA Cadence/Synopsys.','dtvt_ic_design',1200000,'published','https://images.unsplash.com/photo-1518770660439-4636190af475?w=1400&q=80',1,11,'2026-08-09 15:25:27','2026-08-12 14:35:38','2026-08-12 15:25:27'),(18,'Kỹ sư điện tử nhúng (Embedded Engineer)','dtvt-embedded-engineer','Lộ trình ĐTVT: C/C++ nhúng, kiến trúc ARM, RTOS và giao tiếp UART/SPI/I2C.','dtvt_embedded',1200000,'published','https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?w=1400&q=80',1,7,'2026-08-09 15:25:27','2026-08-12 14:35:38','2026-08-12 15:25:27'),(19,'Kỹ sư RF/Anten','dtvt-rf-antenna','Lộ trình ĐTVT: trường điện từ, mạch RF, đo kiểm & mô phỏng anten (CST/HFSS), thông tin vô tuyến.','dtvt_rf',1200000,'published','https://images.unsplash.com/photo-1451187580459-43490279c0fa?w=1400&q=80',1,11,'2026-08-09 15:25:27','2026-08-12 14:35:38','2026-08-12 15:25:27'),(20,'Kỹ sư hạ tầng viễn thông','dtvt-telecom-infrastructure','Lộ trình ĐTVT: truyền dẫn quang, tổng đài & báo hiệu, NMS, vận hành BTS/data center.','dtvt_infra',1200000,'published','https://images.unsplash.com/photo-1544197150-b99a580bb7a8?w=1400&q=80',1,7,'2026-08-09 15:25:28','2026-08-12 14:35:39','2026-08-12 15:25:28');
