INSERT INTO `courses` (`id`, `user_id`, `category_id`, `program_type_id`, `program_id`, `major_id`, `curriculum_id`, `title`, `slug`, `description`, `learning_outcomes`, `benefits`, `requirements`, `level`, `trailer_url`, `price`, `course_mode`, `is_credit_bearing`, `credit_value`, `status`, `is_featured`, `reject_reason`, `thumbnail`, `published_at`, `created_at`, `updated_at`, `certificate_template_id`) VALUES (1,4,NULL,NULL,NULL,NULL,NULL,'Khoá học 01','khoa-hoc-01','<p><strong>Khoá học 01</strong> là khoá bổ trợ / marketplace (học linh hoạt, có thể mua lẻ hoặc theo lộ trình nghề) thuộc nhóm <em>học phần PTIT</em>.</p><p>Trang này đang dùng <strong>khung nội dung demo</strong>: giới thiệu, mục tiêu, chương trình học mẫu, đánh giá và hỏi đáp. Bạn có thể chọn 2–3 khoá để thay bằng nội dung thật sau.</p><p>Sau khi ghi danh, học viên đi theo lộ trình: tổng quan → kiến thức nền → thực hành / quiz → assignment &amp; workshop.</p><ul><li>Video / tài liệu khung kèm quiz kiểm tra nhanh</li><li>Bài tập nộp file và buổi live/offline minh họa</li><li>Hỏi đáp với giảng viên phụ trách khoá</li></ul>','[\"Nắm được mục tiêu, phạm vi và thuật ngữ cốt lõi của «Khoá học 01».\", \"Áp dụng được quy trình / kỹ thuật cơ bản qua ví dụ mẫu trong khoá.\", \"Tự kiểm tra kiến thức bằng quiz và hoàn thành assignment khung.\", \"Biết hướng mở rộng / học tiếp theo lộ trình nghề hoặc CTĐT liên quan.\"]','[\"Chương trình học chia theo chương rõ ràng, dễ theo dõi tiến độ.\", \"Có quiz, bài tập và phiên Q&amp;A để luyện tập ngay trên LMS.\", \"Có thể mua lẻ hoặc kết hợp trong lộ trình nghề trên marketplace.\", \"Giảng viên phụ trách có thể cập nhật nội dung thật mà không đổi cấu trúc trang.\"]','[\"Tài khoản LMS và thiết bị có trình duyệt hiện đại (Chrome/Edge/Firefox).\", \"Kiến thức nền tối thiểu đúng trình độ khoá (xem mức độ bên dưới).\", \"Sẵn sàng thanh toán (nếu khoá có phí) hoặc đã được ghi danh demo.\"]','intermediate','https://www.youtube.com/watch?v=zOjov-2OZ0E',1000000,'extension',0,NULL,'pending_review',0,NULL,'https://images.unsplash.com/photo-1516321318423-f06f85e504b3?w=1200&q=80','2026-07-29 15:53:24','2026-08-12 09:04:04','2026-08-12 15:53:24',NULL),(2,5,5,1,1,NULL,1,'Nhập môn Công nghệ thông tin','nhap-mon-cong-nghe-thong-tin','<p><strong>Nhập môn Công nghệ thông tin</strong> là học phần chính quy trong chương trình đào tạo thuộc nhóm <em>Lập trình & phần mềm</em>.</p><p>Trang này đang dùng <strong>khung nội dung demo</strong>: giới thiệu, mục tiêu, chương trình học mẫu, đánh giá và hỏi đáp. Bạn có thể chọn 2–3 khoá để thay bằng nội dung thật sau.</p><p>Sau khi ghi danh, học viên đi theo lộ trình: tổng quan → kiến thức nền → thực hành / quiz → assignment &amp; workshop.</p><ul><li>Video / tài liệu khung kèm quiz kiểm tra nhanh</li><li>Bài tập nộp file và buổi live/offline minh họa</li><li>Hỏi đáp với giảng viên phụ trách khoá</li></ul>','[\"Nắm được mục tiêu, phạm vi và thuật ngữ cốt lõi của «Nhập môn Công nghệ thông tin».\", \"Áp dụng được quy trình / kỹ thuật cơ bản qua ví dụ mẫu trong khoá.\", \"Tự kiểm tra kiến thức bằng quiz và hoàn thành assignment khung.\", \"Biết hướng mở rộng / học tiếp theo lộ trình nghề hoặc CTĐT liên quan.\"]','[\"Chương trình học chia theo chương rõ ràng, dễ theo dõi tiến độ.\", \"Có quiz, bài tập và phiên Q&amp;A để luyện tập ngay trên LMS.\", \"Gắn với học phần chính quy — phục vụ lớp tín chỉ / ghi danh theo CTĐT.\", \"Giảng viên phụ trách có thể cập nhật nội dung thật mà không đổi cấu trúc trang.\"]','[\"Tài khoản LMS và thiết bị có trình duyệt hiện đại (Chrome/Edge/Firefox).\", \"Kiến thức nền tối thiểu đúng trình độ khoá (xem mức độ bên dưới).\", \"Thuộc đúng chương trình / lớp hành chính được ghi danh học phần.\"]','beginner','https://www.youtube.com/watch?v=zOjov-2OZ0E',0,'core',1,3,'published',0,NULL,'https://images.unsplash.com/photo-1547658719-da2b51169166?w=1200&q=80','2026-07-13 09:55:30','2026-08-12 09:55:30','2026-08-12 15:53:24',3),(3,6,5,NULL,NULL,NULL,NULL,'Thực chiến Công nghệ thông tin','thuc-chien-cong-nghe-thong-tin','<p><strong>Thực chiến Công nghệ thông tin</strong> là khoá bổ trợ / marketplace (học linh hoạt, có thể mua lẻ hoặc theo lộ trình nghề) thuộc nhóm <em>Lập trình & phần mềm</em>.</p><p>Trang này đang dùng <strong>khung nội dung demo</strong>: giới thiệu, mục tiêu, chương trình học mẫu, đánh giá và hỏi đáp. Bạn có thể chọn 2–3 khoá để thay bằng nội dung thật sau.</p><p>Sau khi ghi danh, học viên đi theo lộ trình: tổng quan → kiến thức nền → thực hành / quiz → assignment &amp; workshop.</p><ul><li>Video / tài liệu khung kèm quiz kiểm tra nhanh</li><li>Bài tập nộp file và buổi live/offline minh họa</li><li>Hỏi đáp với giảng viên phụ trách khoá</li></ul>','[\"Nắm được mục tiêu, phạm vi và thuật ngữ cốt lõi của «Thực chiến Công nghệ thông tin».\", \"Áp dụng được quy trình / kỹ thuật cơ bản qua ví dụ mẫu trong khoá.\", \"Tự kiểm tra kiến thức bằng quiz và hoàn thành assignment khung.\", \"Biết hướng mở rộng / học tiếp theo lộ trình nghề hoặc CTĐT liên quan.\"]','[\"Chương trình học chia theo chương rõ ràng, dễ theo dõi tiến độ.\", \"Có quiz, bài tập và phiên Q&amp;A để luyện tập ngay trên LMS.\", \"Có thể mua lẻ hoặc kết hợp trong lộ trình nghề trên marketplace.\", \"Giảng viên phụ trách có thể cập nhật nội dung thật mà không đổi cấu trúc trang.\"]','[\"Tài khoản LMS và thiết bị có trình duyệt hiện đại (Chrome/Edge/Firefox).\", \"Kiến thức nền tối thiểu đúng trình độ khoá (xem mức độ bên dưới).\", \"Sẵn sàng thanh toán (nếu khoá có phí) hoặc đã được ghi danh demo.\"]','intermediate','https://www.youtube.com/watch?v=zOjov-2OZ0E',399000,'extension',0,NULL,'published',0,NULL,'https://images.unsplash.com/photo-1512941937669-90a1b58e7e9c?w=1200&q=80','2026-08-04 09:55:30','2026-08-12 09:55:30','2026-08-12 15:53:25',4),(4,7,6,NULL,NULL,NULL,NULL,'Chuyên sâu Công nghệ thông tin','chuyen-sau-cong-nghe-thong-tin','<p><strong>Chuyên sâu Công nghệ thông tin</strong> là khoá bổ trợ / marketplace (học linh hoạt, có thể mua lẻ hoặc theo lộ trình nghề) thuộc nhóm <em>Cơ sở dữ liệu & hệ thống</em>.</p><p>Trang này đang dùng <strong>khung nội dung demo</strong>: giới thiệu, mục tiêu, chương trình học mẫu, đánh giá và hỏi đáp. Bạn có thể chọn 2–3 khoá để thay bằng nội dung thật sau.</p><p>Sau khi ghi danh, học viên đi theo lộ trình: tổng quan → kiến thức nền → thực hành / quiz → assignment &amp; workshop.</p><ul><li>Video / tài liệu khung kèm quiz kiểm tra nhanh</li><li>Bài tập nộp file và buổi live/offline minh họa</li><li>Hỏi đáp với giảng viên phụ trách khoá</li></ul>','[\"Nắm được mục tiêu, phạm vi và thuật ngữ cốt lõi của «Chuyên sâu Công nghệ thông tin».\", \"Áp dụng được quy trình / kỹ thuật cơ bản qua ví dụ mẫu trong khoá.\", \"Tự kiểm tra kiến thức bằng quiz và hoàn thành assignment khung.\", \"Biết hướng mở rộng / học tiếp theo lộ trình nghề hoặc CTĐT liên quan.\"]','[\"Chương trình học chia theo chương rõ ràng, dễ theo dõi tiến độ.\", \"Có quiz, bài tập và phiên Q&amp;A để luyện tập ngay trên LMS.\", \"Có thể mua lẻ hoặc kết hợp trong lộ trình nghề trên marketplace.\", \"Giảng viên phụ trách có thể cập nhật nội dung thật mà không đổi cấu trúc trang.\"]','[\"Tài khoản LMS và thiết bị có trình duyệt hiện đại (Chrome/Edge/Firefox).\", \"Kiến thức nền tối thiểu đúng trình độ khoá (xem mức độ bên dưới).\", \"Sẵn sàng thanh toán (nếu khoá có phí) hoặc đã được ghi danh demo.\"]','advanced','https://www.youtube.com/watch?v=HXV3zeQKqGY',549000,'extension',0,NULL,'published',0,NULL,'https://images.unsplash.com/photo-1544197150-b99a580bb7a8?w=1200&q=80','2026-07-20 09:55:30','2026-08-12 09:55:30','2026-08-12 15:53:25',2),(5,8,7,NULL,NULL,NULL,NULL,'Dự án cuối khóa Công nghệ thông tin','du-an-cuoi-khoa-cong-nghe-thong-tin','<p><strong>Dự án cuối khóa Công nghệ thông tin</strong> là khoá bổ trợ / marketplace (học linh hoạt, có thể mua lẻ hoặc theo lộ trình nghề) thuộc nhóm <em>Trí tuệ nhân tạo</em>.</p><p>Trang này đang dùng <strong>khung nội dung demo</strong>: giới thiệu, mục tiêu, chương trình học mẫu, đánh giá và hỏi đáp. Bạn có thể chọn 2–3 khoá để thay bằng nội dung thật sau.</p><p>Sau khi ghi danh, học viên đi theo lộ trình: tổng quan → kiến thức nền → thực hành / quiz → assignment &amp; workshop.</p><ul><li>Video / tài liệu khung kèm quiz kiểm tra nhanh</li><li>Bài tập nộp file và buổi live/offline minh họa</li><li>Hỏi đáp với giảng viên phụ trách khoá</li></ul>','[\"Nắm được mục tiêu, phạm vi và thuật ngữ cốt lõi của «Dự án cuối khóa Công nghệ thông tin».\", \"Áp dụng được quy trình / kỹ thuật cơ bản qua ví dụ mẫu trong khoá.\", \"Tự kiểm tra kiến thức bằng quiz và hoàn thành assignment khung.\", \"Biết hướng mở rộng / học tiếp theo lộ trình nghề hoặc CTĐT liên quan.\"]','[\"Chương trình học chia theo chương rõ ràng, dễ theo dõi tiến độ.\", \"Có quiz, bài tập và phiên Q&amp;A để luyện tập ngay trên LMS.\", \"Có thể mua lẻ hoặc kết hợp trong lộ trình nghề trên marketplace.\", \"Giảng viên phụ trách có thể cập nhật nội dung thật mà không đổi cấu trúc trang.\"]','[\"Tài khoản LMS và thiết bị có trình duyệt hiện đại (Chrome/Edge/Firefox).\", \"Kiến thức nền tối thiểu đúng trình độ khoá (xem mức độ bên dưới).\", \"Sẵn sàng thanh toán (nếu khoá có phí) hoặc đã được ghi danh demo.\"]','intermediate','https://www.youtube.com/watch?v=aircAruvnKk',699000,'extension',0,NULL,'published',0,NULL,'https://images.unsplash.com/photo-1620712943543-bcc4688e7485?w=1200&q=80','2026-07-21 09:55:30','2026-08-12 09:55:30','2026-08-12 15:53:25',1),(6,9,9,1,1,NULL,1,'Nhập môn Quản trị kinh doanh','nhap-mon-quan-tri-kinh-doanh','<p><strong>Nhập môn Quản trị kinh doanh</strong> là học phần chính quy trong chương trình đào tạo thuộc nhóm <em>Marketing & thương mại</em>.</p><p>Trang này đang dùng <strong>khung nội dung demo</strong>: giới thiệu, mục tiêu, chương trình học mẫu, đánh giá và hỏi đáp. Bạn có thể chọn 2–3 khoá để thay bằng nội dung thật sau.</p><p>Sau khi ghi danh, học viên đi theo lộ trình: tổng quan → kiến thức nền → thực hành / quiz → assignment &amp; workshop.</p><ul><li>Video / tài liệu kh